library(Luciernaga)
library(dplyr)

TheUnstained <- read.csv("data/Unstained3L.csv", check.names=FALSE)
TheUnstained <- TheUnstained |> select(-Experiment, -Condition, -Count, -Sample) |> slice(1)
Unstained <- TheUnstained

Panel <- file.path("data", "Panel.csv")
Panel <- read.csv(Panel, check.names=FALSE) |> dplyr::filter(Day %in% c(1))
GT <- FluorophoreMatrix(data=Panel, NumberDetectors = 38)
